// gpt-image-2：GrsAI /v1/api/generate；aspectRatio 直接传比例（接口支持比例或 1K 像素）。
const body = { model, prompt, images: images || [], aspectRatio: String(params.aspectRatio || \"auto\"), replyType: \"json\" };
const data = await request({
  method: \"post\",
  url: \"/api/generate\",
  headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${apiKey}` },
  data: body,
});
if (data.status === \"succeeded\" && (data.results || []).length) {
  const urls = data.results.map((item) => item.url).filter(Boolean);
  if (urls.length) return urls;
}
if (data.status === \"running\" && data.id) {
  try {
    return await poll(
      () => request({ method: \"get\", url: `/api/generate/query?id=${encodeURIComponent(data.id)}`, headers: { Authorization: `Bearer ${apiKey}` } }),
      (state) => state.status === \"succeeded\" ? (state.results || []).map((item) => item.url).filter(Boolean) : null,
      { intervalMs: 2500, timeoutMs: 300000 },
    );
  } catch (error) {
    if (String(error.message || \"\").includes(\"404\")) throw new Error(\"GrsAI 异步查询端点未配置，请使用 replyType=json 同步模式\");
    throw error;
  }
}
throw new Error(data.error || `生成失败：status=${data.status}`);

// gpt-image-2-vip：仅接受 1K-4K 像素。脚本按文档「vip 比例参考表」把 比例×分辨率档位 换算成像素。
const VIP_PIXELS = {
  \"1:1\": [\"1024x1024\", \"2048x2048\", \"2880x2880\"],
  \"1:2\": [\"768x1536\", \"1536x3072\", \"1920x3840\"],
  \"2:1\": [\"1536x768\", \"3072x1536\", \"3840x1920\"],
  \"3:2\": [\"1536x1024\", \"2048x1360\", \"3504x2336\"],
  \"2:3\": [\"1024x1536\", \"1360x2048\", \"2336x3504\"],
  \"4:3\": [\"1152x864\", \"2304x1728\", \"3264x2448\"],
  \"3:4\": [\"864x1152\", \"1728x2304\", \"2448x3264\"],
  \"5:4\": [\"1120x896\", \"2240x1792\", \"3200x2560\"],
  \"4:5\": [\"896x1120\", \"1792x2240\", \"2560x3200\"],
  \"16:9\": [\"1280x720\", \"2048x1152\", \"3840x2160\"],
  \"9:16\": [\"720x1280\", \"1152x2048\", \"2160x3840\"],
  \"21:9\": [\"1456x624\", \"2912x1248\", \"3840x1648\"],
  \"9:21\": [\"624x1456\", \"1248x2912\", \"1648x3840\"],
};
const RES_INDEX = { \"1K\": 0, \"2K\": 1, \"4K\": 2 };
function vipPixels() {
  const ratio = String(params.aspectRatio || \"auto\");
  const res = String(params.resolution || \"2K\");
  const list = VIP_PIXELS[ratio];
  const idx = RES_INDEX[res];
  if (list && idx !== undefined && list[idx]) return list[idx];
  return \"2048x2048\";
}
const body = { model, prompt, images: images || [], aspectRatio: vipPixels(), replyType: \"json\" };
const data = await request({
  method: \"post\",
  url: \"/api/generate\",
  headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${apiKey}` },
  data: body,
});
if (data.status === \"succeeded\" && (data.results || []).length) {
  const urls = data.results.map((item) => item.url).filter(Boolean);
  if (urls.length) return urls;
}
if (data.status === \"running\" && data.id) {
  try {
    return await poll(
      () => request({ method: \"get\", url: `/api/generate/query?id=${encodeURIComponent(data.id)}`, headers: { Authorization: `Bearer ${apiKey}` } }),
      (state) => state.status === \"succeeded\" ? (state.results || []).map((item) => item.url).filter(Boolean) : null,
      { intervalMs: 2500, timeoutMs: 300000 },
    );
  } catch (error) {
    if (String(error.message || \"\").includes(\"404\")) throw new Error(\"GrsAI 异步查询端点未配置，请使用 replyType=json 同步模式\");
    throw error;
  }
}
throw new Error(data.error || `生成失败：status=${data.status}`);
